function dicebearUrl(look,age=12){
  look=look||{};
  // The seed stays put as people age; changing hair does not regenerate their entire face.
  const variation=String(look.seed??0)+'-'+String(look.face??0);
  const n=(v,len)=>Math.min(len-1,Math.max(0,Number(v)||0));
  const variant=(v)=>'variant'+String(v).padStart(2,'0');
  const query=new URLSearchParams({
    seed:variation,
    skinColor:(look.skin||SKIN_COLORS[2]).replace('#',''),
    hairColor:(look.hair||HAIR_COLORS[0]).replace('#',''),
    hairVariant:DICE_HAIR[n(look.shape, DICE_HAIR.length)],
    hairProbability:age<2?'28':'100',
    eyesColor:DICE_EYES[n(look.eyes,DICE_EYES.length)],
    eyesVariant:variant(1+n(look.face,4)),
    eyebrowsVariant:variant(1+n(look.brows,3)),
    mouthVariant:variant(1+n(look.smile,3)),
    backgroundColor:(look.shirt||OUTFIT_COLORS[0]).replace('#',''),
    glassesProbability:look.glasses?'100':'0',
    earringsProbability:look.earrings?'100':'0',
    detailsVariant:'freckles',
    detailsProbability:look.freckles?'100':'0'
  });
  return DICEBEAR_ENDPOINT+'?'+query.toString();
}
