function ensureExtras(){if(!s)return;s.alignment=Number.isFinite(s.alignment)?Math.max(-100,Math.min(100,s.alignment)):0;s.legal={record:0,heat:0,probation:0,jailYears:0,detention:0,suspensions:0,...s.legal};s.injury=s.injury||null;s.clubs=Array.isArray(s.clubs)?s.clubs:[];s.schoolTrouble=s.schoolTrouble||0;s.flags=s.flags||{};s.eventsSeen=s.eventsSeen||{};ensureWorld();for(const p of s.people||[])p.status=p.status||{};}
function morality(){const n=s.alignment||0;return n<=-65?'Notorious':n<=-30?'Rebel':n<=-10?'Troublemaker':n<20?'Unpredictable':n<55?'Good egg':'Local hero';}
function bondLabel(p){const status=p?.status?.[s.playerId];return status==='best'?'💜 Best friend':status==='rival'?'⚡ Rival':bondTo(p)<=22?'😬 On bad terms':bondTo(p)>=80?'Close friend':'Friend';}
function setStatus(p,status){if(!p)return;p.status??={};p.status[s.playerId]=status;if((status==='best'||status==='rival')&&!s.friendIds.includes(p.id)&&!isFamily(me(),p))s.friendIds.push(p.id);}
function statPenalty(k,n){if(k==='alignment')s.alignment=Math.max(-100,Math.min(100,s.alignment+n));else if(k==='grades')s.grades=lim(s.grades+n);else statChange({[k]:n});}
function bruise(type='sprain'){const options={bruise:{name:'Bad bruising',years:1,health:-8,cost:75},sprain:{name:'Sprained ankle',years:1,health:-14,cost:230},fracture:{name:'Broken bone',years:2,health:-27,cost:1100},concussion:{name:'Concussion',years:2,health:-33,cost:2100},internal:{name:'Serious internal injury',years:3,health:-42,cost:5300}};const v=options[type]||options.sprain;if(s.injury&&s.injury.years>=v.years)return; s.injury={...v,type};statChange({health:v.health,stress:12,cash:-v.cost});addLog('🏥','A trip to urgent care',`The doctor diagnoses ${v.name.toLowerCase()}. Recovery takes time, and the bill comes to ${fmt(v.cost)}.`, 'injury');}
function consequences(x={},ctx={}){if(!x)return;const fx={};for(const [k,v] of Object.entries(x)){if(['happiness','health','smarts','creativity','confidence','reputation','stress','grades','cash',...Object.keys(s.skills)].includes(k))fx[k]=v;}statChange(fx);if(x.alignment)s.alignment=Math.max(-100,Math.min(100,s.alignment+x.alignment));if(x.heat)s.legal.heat=Math.max(0,s.legal.heat+x.heat);if(x.record){s.legal.record+=x.record;addLog('📋','On your record','This mistake will follow you longer than the awkward conversation.','legal');}if(x.detention){s.legal.detention+=x.detention;statChange({grades:-3*x.detention});addLog('🪑','Detention',`${x.detention} detention(s) added to your school record.`,'legal');}if(x.suspension){s.legal.suspensions+=x.suspension;statChange({grades:-9*x.suspension,reputation:-6});addLog('🚫','Suspended',`You were suspended from school. The work you missed still counts.`,'legal');}if(x.probation)s.legal.probation=Math.max(s.legal.probation,x.probation);if(x.jail&&s.age>=18){s.legal.jailYears=Math.max(s.legal.jailYears,x.jail);s.jobId=null;addLog('🔒','Sentenced',`You received a ${x.jail}-year sentence. You can still read, exercise, and keep in touch with family.`, 'legal');}if(x.injury)bruise(x.injury);if(x.bond){const p=byId(ctx[x.target||'friendId']);if(p)relate(p,x.bond);}if(x.social){let p=byId(ctx[x.target||'friendId']);if(!p&&x.social==='rival')p=makeFriend(true);setStatus(p,x.social);}if(x.newFriend){const p=makeFriend();if(x.social)setStatus(p,x.social);}if(x.flag)s.flags[x.flag]=true;if(x.clearFlag)delete s.flags[x.clearFlag];if(x.follow)s.promises.push({year:s.year+(x.follow.years||1),text:fill(x.follow.text,ctx),effects:x.follow.effects||{},source:'Old choices'});}
function clubChoice(){if(s.age<7||s.age>=21){say('School clubs are for ages 7–20.');return;}if(s.energy<1){say('You need an activity point first.');return;}const choices=CLUBS.filter(c=>s.age>=c.age).map(c=>({label:`${c.icon} ${c.name}${s.clubs.includes(c.id)?' · MEMBER':''}`,note:c.detail,run:()=>{if(s.clubs.includes(c.id)){detailedClubSession(c.id);return}if(s.clubs.length>=2){say('You can join two clubs at once. Leave one to switch.');return;}s.clubs.push(c.id);s.energy--;statChange({confidence:3,social:2});addLog(c.icon,'Joined '+c.name,`You signed up for ${c.name.toLowerCase()}. Club meetings and competitions can now come up in your story.`);save();render();openModal({icon:c.icon,title:'You are in!',text:`Your name is on the ${c.name} roster. Your first meeting is coming up.`,choices:[{label:'Nice',run:()=>{}}]})}}));openModal({icon:'🏫',title:'Pick your club',text:`You are in ${s.clubs.length}/2 clubs. Practice your skills here, meet people and run into unique club stories.`,choices:[...choices,...(s.clubs.length?[{label:'🚪 Leave a club',run:leaveClub}]:[])]});}
function leaveClub(){openModal({icon:'🎒',title:'Leave which club?',text:'Sometimes a club is not your thing anymore.',choices:s.clubs.map(id=>{const c=CLUBS.find(c=>c.id===id);return {label:c.name,run:()=>{s.clubs=s.clubs.filter(x=>x!==id);addLog('🚪','Left '+c.name,'You gave back your club badge. Nobody knew where the badge was supposed to go.');save();render();}}})});}
function clubSession(id){const c=CLUBS.find(c=>c.id===id);if(!c||s.energy<1)return;s.energy--;const skill=c.skill==='smarts'?'smarts':c.skill;const score=c.skill==='smarts'?s.stats.smarts:s.skills[skill];const succeeded=prob(Math.min(.9,.36+score*.006));const story=succeeded?pick([`Your ${c.name.toLowerCase()} project gets noticed. Someone actually applauds.`,`You help the team pull off a tricky challenge.`,`A teammate asks you to lead the next meeting.`]):pick([`You fumble at ${c.name.toLowerCase()}. Your rival notices.`,`The meeting goes badly. The group votes to try a different plan.`,`You're benched for the big event. It stings.`]);statChange({[skill]:succeeded?10:6,confidence:succeeded?5:-4,stress:succeeded?-2:5,happiness:succeeded?5:-3});addLog(c.icon,c.name,story);save();render();openModal({icon:c.icon,title:c.name,text:story,choices:[{label:'Go on',run:()=>{}}]});}
function petAdoption(){if(s.cash<85){say('Adoption costs $85.');return;}if(s.pets.filter(p=>!p.died).length>=3){say('Three pets is the maximum.');return;}openModal({icon:'🐾',title:'Who is coming home?',text:'The shelter has a few new faces. Adopting costs $85.',choices:[['dog','🐶 Dog'],['cat','🐱 Cat'],['rabbit','🐰 Rabbit'],['hamster','🐹 Hamster'],['bird','🐦 Bird']].map(([kind,label])=>({label,run:()=>petNameChoice(kind)}))});}
function petNameChoice(kind){const names={dog:['Scout','Maple','Bowie','Roxy'],cat:['Juniper','Salem','Nori','Cleo'],rabbit:['Hazel','Thistle','Mabel','Clover'],hamster:['Pip','Nibbles','Bean','Gus'],bird:['Kiwi','Pico','Echo','Skye']}[kind];const finish=name=>{if(!name||!name.trim())return;s.cash-=85;adoptPet(kind,name);save();render();say('Welcome home, '+name+'!')};openModal({icon:'🐾',title:'Name your new '+kind,text:'Pick a name, or give them one of your own.',choices:[...names.map(name=>({label:name,run:()=>finish(name)})),{label:'✏️ Choose my own name',run:()=>{const name=window.prompt('Your '+kind+'’s name (max 24 characters):','');if(name)finish(name.trim().slice(0,24));}},{label:'Back to the shelter',run:petAdoption}]});}
function socialAction(id,kind){const p=byId(id);if(!p||!alive(p)||s.energy<1){say('No action points, or this person is unavailable.');return;}if(s.legal.jailYears>0&&kind==='fight'){say('You cannot start fights while incarcerated.');return;}s.energy--;let title='',story='',fx={},status=null,injury=null;const social=s.skills.social||0,sports=(s.skills.sports||0)+personalitySkillBoost('sports'),other=40+(p.personality==='competitive'?18:0)+(p.personality==='chaotic'?12:0),won=prob(Math.max(.16,Math.min(.88,.42+(sports-other)*.006)));if(kind==='best'){if(bondTo(p)<72){say('You need a bond of 72+ to become best friends.');s.energy++;return;}setStatus(p,'best');title='Best friends, officially';story=`You and ${p.name} promise to have each other's backs. Within the hour, you already disagree about what to get for lunch.`;fx={happiness:9,confidence:5};relate(p,9);}else if(kind==='tease'){title='A joke that landed badly';story=prob(.3)?`${p.name} laughs. Everybody else looks uncomfortable.`:`${p.name} goes quiet. You've clearly crossed a line.`;fx={alignment:-8,reputation:-3,confidence:2};relate(p,-13);if(bondTo(p)<25)setStatus(p,'rival');}else if(kind==='rumor'){title='You started a rumor';const caught=prob(.58-(social*.002));story=caught?`${p.name} finds out where the rumor started. Screenshots travel fast.`:'The rumor spreads. You get the attention you wanted, but you know where it came from.';fx={alignment:-17,reputation:caught?-18:3,stress:caught?12:4};relate(p,-26);if(caught)setStatus(p,'rival');if(caught&&s.age<18)s.legal.detention++;}else if(kind==='standup'){title='You stood your ground';story=prob(.6)?`You tell ${p.name} to cut it out without throwing a punch. People listen.`:`${p.name} rolls their eyes, but backs off for now.`;fx={alignment:9,confidence:8,reputation:5};if(p.status?.[s.playerId]==='rival')relate(p,-4);}else if(kind==='fight'){title='A fight with '+p.name;story=won?`You land a couple of hits before someone separates you. ${p.name} is hurt. The principal wants answers.`:`${p.name} knocks you down hard. You need medical attention, and the whole school is talking.`;fx={alignment:-14,health:won?-8:-20,reputation:won?3:-9,stress:13};relate(p,-32);setStatus(p,'rival');if(!won)injury=prob(.28)?'internal':prob(.5)?'concussion':'sprain';else if(prob(.12))injury='fracture';if(s.age<18){s.legal.suspensions++;s.grades=lim(s.grades-10);s.flags.fightHearing=true;}else{s.legal.heat+=20;if(prob(.42)){s.legal.record++;s.cash=Math.max(0,s.cash-600);}}}else if(kind==='makeup'){title='An uncomfortable truce';if(prob(.35+(social*.004)+personalitySocialModifier(p,'apologize')*.004)){story=`You and ${p.name} finally talk honestly. Not best friends, but no longer enemies.`;setStatus(p,'friend');relate(p,23);fx={alignment:8,happiness:6};}else{story=`${p.name} isn't ready to forgive you. That's fair. Maybe later.`;relate(p,2);fx={stress:3};}}else return;consequences(fx,{friendId:p.id});if(injury)bruise(injury);addLog('🎭',title,story,'social');save();render();openModal({icon:kind==='fight'?'🥊':'🎭',title,text:story+(injury?' Doctors diagnosed an injury. Check your health.':''),choices:[{label:'Keep going',run:()=>{}}]});}
function legalAgeUp(){if(s.injury){s.injury.years--;if(s.injury.years<=0){addLog('💚','Recovered',`Your ${s.injury.name.toLowerCase()} has healed. You can get back to normal activities.`);s.injury=null;}else statChange({stress:2});}if(s.legal.probation>0)s.legal.probation--;s.legal.heat=Math.max(0,s.legal.heat-12);if(s.legal.detention>0){s.legal.detention=Math.max(0,s.legal.detention-2);statChange({stress:3,grades:-2});}if(s.legal.jailYears>0){s.legal.jailYears--;s.energy=1;statChange({confidence:-5,happiness:-9,stress:6});if(!s.legal.jailYears)addLog('🔓','Released',`Your sentence is complete. You still have a record, but you've got choices to make.`);}}
const SC=(label,good,bad,opts={})=>({label,good,bad,twist:bad,v3:true,...opts});
const NE=(id,period,icon,title,text,choices,when=()=>true,priority=false)=>({...E(id,period,icon,title,text,choices,when),priority});

