// LITTLE LIFE 4: all additions run locally in this single HTML file.
const THEME_KEY='little-life-theme-v4';
let chosenTheme='light';
try{chosenTheme=localStorage.getItem(THEME_KEY)||'light';}catch(_){ }
function applyTheme(){document.documentElement.dataset.theme=chosenTheme;const c=document.querySelector('meta[name="theme-color"]');if(c)c.content=chosenTheme==='dark'?'#111523':'#f7f8fe';}
function toggleTheme(){chosenTheme=chosenTheme==='light'?'dark':'light';try{localStorage.setItem(THEME_KEY,chosenTheme);}catch(_){}applyTheme();render();}
applyTheme();
