function ensureWorld(){if(!s)return;s.city??='Maple Falls';s.school??='public';s.allowance=Number.isFinite(s.allowance)?s.allowance:0;s.lastAllowanceRequest??=-99;s.projects??=[];s.trophies??=[];s.transport??='walk';s.vehicles??=[];s.discoveries??=[];s.mysteryYear??=-999;s.instrument??=null;s.adultSchoolSummary??=null;s.activityYears??={};s.lastMovingYear??=-99;s.lastSchoolTransferYear??=-99;s.lastDrivingTestYear??=-99;s.teenJob??=null;s.notes??=[];}
function activityScore(skill){const score=skill==='grades'?s.grades:['smarts','health','confidence','creativity','reputation'].includes(skill)?s.stats[skill]:(s.skills[skill]||0);return Math.max(0,Math.min(100,score+personalitySkillBoost(skill)));}
function energyCost(){if(s.energy<1){say('No time left this year. Age up when you’re ready.');return false;}s.energy--;return true;}
function outcomeModal(icon,title,text,fx={},kind='activity'){consequences(fx,context());addLog(icon,title,text,kind);save();render();openModal({icon,title,text,choices:[{label:'Back to my story →',run:()=>{}}]});}
function namedAchievement(type,theme,skill,icon,options){if(!energyCost())return;const chosen=pick(options),score=activityScore(skill);const roll=Math.random()*72+score*.65-(s.injury?7:0);const quality=roll>=106?'outstanding':roll>=78?'great':roll>=52?'promising':'rough';const remarks={outstanding:['People stop what they’re doing to look. Even you’re impressed.','A stranger asks how long you’ve been doing this.'],great:['It works far better than you expected.','You show it to a friend and they immediately want one.'],promising:['It has problems, but there’s something there.','You can see exactly what you would change next time.'],rough:['It falls apart at the worst possible moment. You learn something anyway.','Nobody is quite sure what you were going for. Neither are you.']}[quality];const gain=quality==='outstanding'?13:quality==='great'?10:quality==='promising'?8:6;const synopsis=PROJECT_BLURBS[chosen]||`${type==='music'?`A ${pick(['gentle','upbeat','wistful','bold'])} piece you play on ${s.instrument||'your favorite instrument'}.`:type==='cooking'?'Your own recipe, made from scratch.':'A creative experiment with plenty of personality.'}`;
 const detail=`You ${theme} “${chosen}.” ${synopsis} ${pick(remarks)} ${quality==='outstanding'?'You might have a real future in this.':''}`;s.projects.unshift({year:s.year,age:s.age,type,title:chosen,quality,skill,icon,description:synopsis});s.projects=s.projects.slice(0,80);s.activityYears[skill]=(s.activityYears[skill]||0)+1;outcomeModal(icon,`“${chosen}” · ${quality}`,detail,{[skill]:gain,happiness:quality==='rough'?-2:4,confidence:quality==='outstanding'?9:quality==='rough'?-3:3,creativity:skill==='art'||skill==='writing'?3:0});}
