function projectMenu(kind){const cfg={art:{icon:'🎨',prompt:'What are you making?',actions:[['painting','Paint a picture'],['sculpture','Make a clay sculpture'],['comic','Draw a comic'],['photography','Take photographs']]},writing:{icon:'✍️',prompt:'What kind of book will you write?',actions:[['fantasy','A fantasy novel'],['mystery','A mystery'],['comedy','A comedy'],['realistic','A realistic story']]},coding:{icon:'💻',prompt:'What do you want to build?',actions:[['game','A video game'],['website','A website'],['robot','A little robot']]},cooking:{icon:'🥘',prompt:'What is on the menu?',actions:[['baking','Bake something'],['dinner','Cook dinner'],['snack','Make snacks']]}}[kind];openModal({icon:cfg.icon,title:cfg.prompt,text:'The result depends on practice, some luck, and the occasional spectacular mistake.',choices:cfg.actions.map(([id,label])=>({label,run:()=>namedAchievement(kind,kind==='art'?({painting:'paint',sculpture:'sculpt',comic:'draw',photography:'photograph'}[id]):kind==='writing'?'write':kind==='coding'?'build':'make',kind,cfg.icon,CREATIONS[kind][id])}))});}
