for(const [period,icon,title,text,a,goodA,badA,b,goodB,badB,skill] of LL5_VIGNETTES){
 const id='ll5_'+period+'_'+title.toLowerCase().replace(/[^a-z0-9]+/g,'_');
 const isBad= /^(Double down|Cheat|Blame|Spread|Sabotage|Lie|Use it in secret|Take the book|Go all in|Fake|Hit back|Swap|Try to get out by lying|Buy it on the spot|Post it online|Join the laughter|Pretend it was intentional)/i.test(b);
 events.push(NE(id,period,icon,title,text,[SC(a,goodA,badA,{skill,ok:{[skill]:7,popularity:period==='teen'?3:0,confidence:3},no:{[skill]:3,confidence:-2}}),SC(b,goodB,badB,{skill,ok:{[skill]:5,alignment:isBad?-10:2,popularity:period==='teen'?(isBad?-3:3):0},no:{[skill]:2,alignment:isBad?-15:0,confidence:-4,popularity:isBad?-8:0}})]));
}
// Fix the original first-word event rather than recycling a generic template.
const firstWordEvent=events.find(e=>e.id==='firstword');
if(firstWordEvent){
 firstWordEvent.title='The very first word';
 firstWordEvent.text='For weeks, every adult in the house has been repeating the same two syllables at you. Today, something finally clicks. Your family is about to quote you forever.';
 firstWordEvent.when=ss=>ss.age>=1&&ss.age<=3;
 firstWordEvent.choices=[
 SC('“Mama!”','Your mother bursts into happy tears, then makes everyone swear you said it first.','It sounds like “mama,” except you were actually pointing at a mango.',{ok:{happiness:9,social:3},no:{happiness:6}}),
 SC('“Dada!”','Your father does a victory lap around the kitchen. Your mother demands a recount.','You call every object in the room “dada,” including the dog.',{ok:{happiness:9,social:3},no:{happiness:5}}),
 SC('“NO!”','You say it loudly, correctly, and with the confidence of a tiny CEO. This becomes a problem.','Your family laughs until you say it to the pediatrician.',{ok:{confidence:8},no:{social:3}}),
 SC('“DOG!”','The dog raises his head. You and the dog are now in a lifelong alliance.','You point at the refrigerator. The dog is wounded by the comparison.',{ok:{happiness:7,animals:5},no:{happiness:4}}),
 SC('“PIZZA!”','Your uncle is so proud he brings an actual pizza the next day.','You repeat it every time you are hungry. The family is not equipped for this.',{ok:{happiness:7},no:{confidence:4}}),
 SC('“UH-OH.”','You say it moments before dropping an entire bowl of cereal. Excellent timing.','The family assumes you are warning them. You are not.',{ok:{smarts:4},no:{creativity:4}}),
 SC('“TAXES.”','Your grandmother calls you a little accountant. You have no idea what you have unleashed.','Your parent stares at the unpaid bills and asks you not to say that again.',{ok:{smarts:6},no:{confidence:3}}),
 SC('“MORE!”','You use it for a second helping. By evening, you use it for everything—including naps.','You only say it when the vegetables have been taken away.',{ok:{happiness:7},no:{confidence:4}})
 ];
}
const LL5_ODDITIES=[
 ['mirror','🪞','The mirror blinks first','At a roadside diner, your reflection takes a sip of its milkshake while you are holding a cup of tea.', 'Your reflection mouths the words “not yet.”',['Pretend you saw nothing','It nods and goes back to being normal.','caution',2],['Ask it a question','It writes tomorrow’s date in condensation.','study',5],['Smash the mirror','The owner hands you a repair bill. Nothing else happens.','explore',-7],'On the way out, the waitress hands you a receipt stamped with a photograph of your childhood home.',['Keep the receipt','Years later the ink is still wet.','keep',2],['Show someone','They see a completely different house in the photo.','friend',5],['Leave it behind','A new receipt appears in your coat.','leave',1]],
 ['moonday','🌕','The moon calls collect','Your phone rings at 2:04 AM. The caller ID says MOON. The voice on the other end asks whether the tides are behaving.', 'The caller seems mildly disappointed with Earth.',['Offer a status update','It thanks you and says your planet has excellent soup.','friendly',6],['Hang up','Your phone screen shows a tiny eclipse for a week.','caution',0],['Ask for a spaceship','The caller says they only handle customer service.','study',2],'The next morning, you discover a postcard in your mailbox. The stamp is a crater.',['Frame it','The postcard slowly changes as the moon moves.','keep',3],['Mail it back','You get a thank-you card three months later.','gift',5],['Sell it online','Every buyer receives an empty envelope.','sell',-3]],
 ['librarystairs','📚','The extra floor','Your town library has always had three floors. Today the elevator button panel has a fourth, labeled “Books Not Yet Written.”', 'A librarian behind the fourth-floor desk looks up. She knows your name.',['Browse the shelves','You find a novel with your name on the spine. The pages are blank.','study',4],['Ask about the rules','She tells you books can only leave when their stories are finished.','question',2],['Run away','The elevator returns you to the history section.','caution',1],'A book starts writing a sentence on its own: “When the door opened...”',['Finish the sentence','The book laughs. That is not a sound a book should make.','keep',4],['Close the cover','The book politely writes THE END.','release',3],['Steal the book','It vanishes. Your pocket is full of bookmarks.','chaos',-5]],
 ['secondshadow','👤','The second shadow','On a cloudy afternoon you notice two shadows stretching behind you. One is moving slightly ahead of the other.', 'The extra shadow is pointing toward an alley painted with stars.',['Follow carefully','You find a tiny theater playing scenes from your life to an audience of hats.','explore',-3],['Wave at it','It waves back, with fingers you do not have.','friendly',5],['Stand very still','The second shadow starts tapping its foot impatiently.','caution',2],'The shadow returns with a message scratched onto the pavement: “Thank you for noticing.”',['Say you are welcome','For a second, the whole street feels lighter.','friendly',4],['Photograph it','The photo has only one shadow. Of course it does.','camera',1],['Forget about it','You never see the second shadow again.','release',2]],
 ['gnome','🍄','The garden gnome council','Your garden gnome moves six inches overnight. A tiny envelope appears beside it. You are summoned to the Council of Small Hats.', 'At midnight, six lawn ornaments wait beneath the oak tree.',['Attend the hearing','You are accused of neglecting a hydrangea. The charges are shockingly specific.','study',4],['Bring cupcakes','The council debates the frosting for an hour.','gift',5],['Refuse to participate','Your garden fills with tiny protest signs.','chaos',-2],'The head gnome holds up a mushroom-shaped gavel and demands a verdict.',['Plead guilty','You agree to water the garden twice a week.','help',6],['Defend yourself','Your closing argument wins. The gnomes salute you.','study',3],['Declare yourself king','The council unanimously votes you a menace.','chaos',-7]],
 ['train','🚂','Platform zero','You miss the last train, then notice a platform between tracks two and three. Its timetable lists places that do not exist.', 'A conductor in an old-fashioned uniform asks for your destination.',['Ask for the map','The map shows a town named after your first pet.','study',3],['Board without asking','You glimpse a skyline made of clocks.','explore',-3],['Call a friend','Your friend hears train whistles through the phone.','friend',2],'The conductor hands you a one-way ticket stamped “RETURN.”',['Keep it','The ticket becomes a warm metal token.','keep',4],['Give it back','The conductor nods. Platform zero disappears.','release',5],['Sell the story','Nobody believes you, but a zine pays for the article.','sell',-4]],
 ['seaofstars','🌌','The puddle of stars','After a storm, one puddle reflects the night sky even though the sun is blazing overhead.', 'A tiny comet swims through its reflection like a fish.',['Touch the water','Your fingertips smell like snow. A childhood memory returns vividly.','explore',2],['Fetch a jar','The starlight leaks through the glass.','study',4],['Put up a warning sign','People start gathering. For one afternoon, everyone looks down to see the sky.','friend',6],'The puddle begins shrinking as the clouds break.',['Protect it with a blanket','The blanket turns briefly transparent, showing galaxies.','keep',3],['Watch until it vanishes','It leaves a single silver pebble behind.','keep',4],['Pour it into a drain','A distant thunderclap sounds suspiciously annoyed.','chaos',-6]],
 ['futurepackage','📦','The package from 2091','A parcel arrives addressed to you, with a postage date sixty-five years in the future.', 'Inside is a small device displaying a recording of you saying “Trust the woman with the yellow scarf.”',['Study the device','It shows a miniature weather map of next Friday.','study',6],['Hide it under your bed','It starts quietly playing your favorite childhood song.','keep',3],['Give it to the post office','The clerk says this is not their weirdest Tuesday.','caution',4],'At the bus stop, a woman in a yellow scarf asks whether you have the time.',['Tell her the truth','She smiles as though relieved. “It worked,” she says.','friendly',7],['Ask who sent the parcel','She gives you a tiny key shaped like a star.','study',3],['Avoid her','The device shuts off. A quiet choice, and perhaps a wise one.','caution',1]],
 ['giantduck','🦆','The thirty-foot duck','A duck the size of a bus is calmly standing in the supermarket parking lot. Everyone else is acting normal.', 'The duck leans down and steals a baguette.',['Offer a second baguette','The duck bows as if you are royalty.','gift',5],['Call animal control','The operator asks whether you have tried gently shooing it.','study',2],['Climb onto its back','You are politely dropped in a puddle.','explore',-5],'The duck flies away over the rooftops, leaving a single enormous feather.',['Put the feather in a museum','It attracts a crowd, then slowly shrinks to normal size.','study',5],['Keep it as a souvenir','The feather works as an excellent blanket.','keep',3],['Start a duck cult','Nobody comes to the first meeting.','chaos',-4]],
 ['whisperwoods','🌳','The forest votes','A tree beside the school playground slowly bends down and asks you to settle a dispute between two trees.', 'One tree says a squirrel stole its acorns. The other claims the squirrel is an artist.',['Hold a fair trial','You question the squirrel. It throws an acorn and flees.','study',5],['Side with the artistic squirrel','The trees sigh. You are appointed Minister of Leaves.','friendly',2],['Walk away','The tree follows you for six steps, which is alarming for a tree.','caution',1],'The forest offers you a reward for resolving its internal affairs.',['Ask for nothing','The leaves spell your name once each autumn.','gift',6],['Ask for a treasure map','The map leads to a buried toy spaceship.','keep',2],['Demand gold','The trees drop seventeen pounds of acorns on your head.','chaos',-4]],
 ['tapestry','🧶','A tapestry of tomorrow','At a flea market, an old tapestry shows your town, except one house is floating.', 'When you look away and back, the floating house moves a little.',['Buy the tapestry','You pay five dollars and spend years wondering about it.','keep',3],['Ask the seller who made it','She says it has always been for sale, but nobody remembers bringing it in.','study',4],['Photograph it','The picture shows a completely normal tapestry.','camera',2],'That night the tapestry shows your bedroom window illuminated in blue.',['Stay awake and watch','At 3 AM the light blinks three times, then stops.','study',4],['Take it outside','The stars above line up like stitches.','explore',2],['Throw it away','The trash collector leaves it beside your door.','chaos',-3]],
 ['moonrabbit','🐇','The rabbit in a spacesuit','A white rabbit wearing a miniature silver helmet sits in your yard. A tiny badge reads “LUNAR POST.”', 'It opens a briefcase filled with letters addressed to people you know.',['Deliver the letters','People receive notes from friends they have not seen in years.','help',7],['Read your own letter','It contains one sentence: “Remember the blue door.”','keep',2],['Take the briefcase','The rabbit stamps your hand with a crescent moon and takes it back.','chaos',-5],'The rabbit climbs into a tiny cardboard capsule and prepares to leave.',['Wave goodbye','It salutes and vanishes in a puff of glitter.','friendly',4],['Offer a carrot','It accepts politely, then leaves you a moon rock.','gift',5],['Ask for a ride','The rabbit shakes its head and points to your shoes.','caution',1]]
];
for(const [id,icon,title,open,q1,a,b,c,q2,d,e,f] of LL5_ODDITIES){ODDITIES.push({id:'ll5_'+id,icon,title,min:7,max:105,open,steps:[{question:q1,choices:[a,b,c]},{question:q2,choices:[d,e,f]}]});}
