 const id='ll5_wild_'+title.toLowerCase().replace(/[^a-z0-9]+/g,'_');
 events.push(NE(id,period,icon,title,text,[SC(label,good,bad,{skill,ok:{[skill]:7,happiness:7,popularity:5},no:{[skill]:3,stress:4}}),SC('Take the quiet option',`You step back and watch. ${text.includes('school')?'A friend is impressed by your restraint.':'Some stories are better observed from a safe distance.'}`,`You miss the excitement, but a stranger tells you the rest later. It sounds even more ridiculous.`,{ok:{confidence:2},no:{happiness:-2}})]));
