// Choices at school feed into peer standing, without duplicating morality.
const ll5OldSocialAction=socialAction;
socialAction=function(id,kind){if(!s)return;ensureLL5();const was=s.energy,oldBond=bondTo(byId(id));ll5OldSocialAction(id,kind);if(s.energy<was){const n=kind==='bully'?-6:kind==='fight'?-9:kind==='best'?10:kind==='makeup'?4:kind==='rumor'?4:0;s.popularity=lim(s.popularity+n);save();}}
const ll5OldAnnualSchool=annualSchool;
annualSchool=function(){ll5OldAnnualSchool();if(!s)return;ensureLL5();if(s.age>=5&&s.age<=17){const reput=s.stats.reputation,drift=s.popularity>70?-2:s.popularity<25?3:0;s.popularity=lim(s.popularity+Math.round((reput-50)/24)+drift);if(s.grades<30&&s.popularity>70&&prob(.2)){addLog('📚','Popular, not prepared','Your friends love you. Your report card does not. A teacher asks whether you want tutoring.','school');}if(s.grades>88&&s.popularity<30&&prob(.25)){addLog('🏅','Academic ace','Your teachers know you by name. The popular table still does not. That may be okay.','school');}}};
// The story panels expose tangible, saved accomplishments, not just raw scores.
const ll5OldActivities=activities;
activities=function(){if(!s)return '';ensureLL5();const added=LL5_HOBBIES.map(h=>activityTile(h[1],h[2],h[3]+` · ${s.skills[h[0]]}/100`, 'hobby:'+h[0])).join('');const work=ll5OldActivities();if(s.age<4)return work;const last=s.hobbyHistory.slice(0,2).map(m=>`<div class="ll5-creative-log"><b>${esc(m.icon)} ${esc(m.title)}</b><span>${esc(m.outcome)}</span></div>`).join('');return work.replace('<h2 class="heading">🎨 Hobbies & passions</h2>',`<h2 class="heading">Choose your next obsession</h2><p class="ll5-section-note">The thing you practise today might get you a trophy, a career—or a very embarrassing nickname.</p>`).replace('</div></section><section class="card pad"><h2 class="heading">🌻 Everyday choices',added+`</div></section>${last?`<section class="card pad ll5-last-made"><h2 class="heading">Previously, on your hobbies…</h2>${last}</section>`:''}<section class="card pad"><h2 class="heading">🌻 Everyday choices`);};
const ll5OldLifeIndicators=lifeIndicators;
lifeIndicators=function(){if(!s)return '';ensureLL5();const p=s.popularity;
 const label=p>=85?'School celebrity':p>=65?'Well-liked':p>=40?'Known around town':p>=20?'Under the radar':'Outsider';
 return ll5OldLifeIndicators()+`<section class="card pad mini-side ll5-standing"><h2 class="heading">🏫 Your social standing</h2><div class="ll5-standing-score"><b>${p}</b><span>/100 · ${label}</span></div><div class="progress"><i style="width:${p}%;background:${p<30?'#e9a17e':'#70aaab'}"></i></div></section>`;};
const ll5OldHome=home;
home=function(){if(!s)return '';ensureLL5();let html=ll5OldHome();const score=s.popularity,label=score>=75?'Everyone seems to know you.':score>=45?'You have your crowd.':score>=25?'You mostly keep to yourself.':'People overlook you—but that might change.';
 const hobbies=s.hobbyHistory.slice(0,2).map(m=>`<div class="ll5-feature-story"><span>${esc(m.icon)}</span><div><b>${esc(m.title)}</b><small>${esc(m.outcome)}</small></div></div>`).join('');
 const extra=`<section class="card pad ll5-feature"><div class="ll5-eyebrow">AROUND TOWN</div><h2>Word gets around.</h2><div class="ll5-pop-row"><strong>${score}<small>/100</small></strong><div><b>${score>=65?'Talk of the town':score>=35?'In the mix':'A quiet presence'}</b><p>${label}</p></div></div><div class="progress"><i style="width:${score}%;background:#ce89a1"></i></div>${hobbies?`<h3>Recent adventures</h3>${hobbies}`:''}</section>`;
 return html.replace('</section>', '</section>'+extra);
};
const ll5OldJournal=journalTab;
journalTab=function(){if(!s)return '';ensureLL5();const html=ll5OldJournal();const arcs=Object.entries(s.storyLedger).map(([id,data])=>{const a=LL5_ARCS.find(x=>x.id===id);return a?`<div class="ll5-creative-log"><b>${a.icon} ${esc(a.name)}</b><span>${data.completed?'Story complete':`Part ${data.step+1} may happen later`}${data.lastChoice?' · Last choice: '+esc(data.lastChoice):''}</span></div>`:''}).join('');const arts=s.hobbyHistory.slice(0,12).map(m=>`<div class="ll5-creative-log"><b>${esc(m.icon)} ${esc(m.title)}</b><span>${m.year} · ${esc(m.outcome)}</span></div>`).join('');return html+`<section class="card pad"><h2 class="heading">📜 Stories still following you</h2>${arcs||'<p class="lead">Nothing has come back to bite you. Yet.</p>'}</section><section class="card pad"><h2 class="heading">🎲 What you actually did</h2>${arts||'<p class="lead">Nothing to show. What have you been doing all these years?</p>'}</section>`;};
const ll5OldStyle=renderStyleEditor;
renderStyleEditor=function(){ll5OldStyle();const head=document.querySelector('.new-head');if(head){const theme=document.createElement('button');theme.className='btn alt tiny ll5-editor-theme';theme.setAttribute('data-do','theme');theme.textContent=chosenTheme==='dark'?'☀️ Light mode':'🌙 Dark mode';head.prepend(theme);}}
// Give the surreal middle-of-life incidents their own second choice rather than a repeated stock exit.
