function hobbyState(){if(!s)return;s.hobbyWorld??={last:{},streak:{},milestones:{},notes:[],party:{trust:50,level:1,quests:0,fortune:0},music:{songs:[],gigs:0,band:null},decayYears:{}};
 const w=s.hobbyWorld;w.last??={};w.streak??={};w.milestones??={};w.notes??=[];w.party??={trust:50,level:1,quests:0,fortune:0};w.party.trust??=50;w.party.level??=1;w.party.quests??=0;w.party.fortune??=0;w.music??={songs:[],gigs:0,band:null};w.music.songs??=[];w.music.gigs??=0;w.music.band??=null;w.decayYears??={};for(const id of Object.keys(HW_EXTRA_SKILLS))s.skills[id]??=0;}
function hobbyRecord(skill,title,result,success,delta){hobbyState();const w=s.hobbyWorld;w.last[skill]=s.year;w.streak[skill]=(w.streak[skill]||0)+1;s.activityYears??={};s.activityYears[skill]=(s.activityYears[skill]||0)+1;s.hobbyHistory??=[];s.hobbyHistory.unshift({icon:skillIcons[skill]||'✨',title,year:s.year,outcome:result,skill,success});s.hobbyHistory=s.hobbyHistory.slice(0,90);w.notes.unshift({skill,title,year:s.year,age:s.age,result,delta});w.notes=w.notes.slice(0,120);}
function hobbyCallback(skill,source,title){if((s.skills[skill]||0)<35||!prob(.16))return;const buddy=pick(friends().filter(alive))?.name||'a friend from town';const tails=[`${buddy} remembers your ${source} and asks whether you'll show them how you did it.`,`A beginner from the ${source} writes to say your advice helped them through their first attempt.`,`You return to the ${source} and find somebody has been practicing specifically to beat your best result.`];s.promises.push({year:s.year+1+r(3),icon:skillIcons[skill]||'✨',title:`The ${source} comes back around`,text:pick(tails),effects:{confidence:3,reputation:3}});}
function hobbyDo(skill,scene,settings={}){if(!s||s.energy<1){say('Your year is full. Another birthday is only a tap away.');return;}hobbyState();const before=s.skills[skill]||0;const difficulty=settings.difficulty??47;const mastery=before>=80;const advantage=settings.bonus||0;
 const chance=Math.min(.94,Math.max(.15,.34+before*.006+(s.stats.confidence-50)*.0015+advantage-difficulty*.0015));
 const success=prob(chance),twist=prob(.13);let story=twist&&scene[3]?scene[3]:success?scene[1]:scene[2];
 const gain=Math.min(100-before,success?4+r(6):2+r(4));const category=skill==='fencing'||skill==='dueling'||skill==='hiking'||skill==='horseback'||skill==='sailing'||skill==='fishing'?'health':skill==='archaeology'||skill==='paleontology'||skill==='languages'||skill==='robotics'||skill==='birdwatching'||skill==='geocaching'?'smarts':'creativity';
 const fx={[skill]:gain,happiness:success?4:twist?3:-3,confidence:success?5:twist?1:-3,stress:success?-2:2,[category]:success?2:0};
 if(!success&&prob(.09)){if(['fencing','dueling','horseback','sailing','hiking'].includes(skill)){fx.health=-3-r(4);story+=' You need a few days to recover from a bruised knee.';}else{fx.cash=s.age>=18?-20-r(65):0;story+=' Your supplies need replacing.';}}
 if((skill==='archaeology'||skill==='paleontology'||skill==='languages'||skill==='robotics')&&s.age<18)fx.grades=success?2:0;
 if((skill==='fencing'||skill==='debate'||skill==='standup'||skill==='magic')&&s.age<18)fx.popularity=success?4:-1;
 if(success&&before>=45&&prob(.18)){if(s.age>=18)fx.cash=30+r(170);else fx.reputation=3;story+=' Somebody offers to pay for your help.';}
 const next=before+gain,rank0=hobbyRank(before),rank1=hobbyRank(next);if(rank0!==rank1){story+=` You have reached ${rank1.toLowerCase()} level.`;fx.reputation=5;}
 if(next>=90&&!s.hobbyWorld.milestones[skill]){s.hobbyWorld.milestones[skill]=s.year;s.trophies??=[];s.trophies.push(`${skill} mastery · ${s.year}`);fx.reputation=(fx.reputation||0)+8;story+=' Your name goes up on the local club’s wall of honor.';}

 if(mastery&&success&&prob(.38)){const special={fencing:'Your old instructor nods from across the strip. They stopped giving compliments years ago.',archaeology:'A museum curator asks to see your field notes, not just the artifact.',birdwatching:'Other watchers stop scanning the trees and wait for you to identify the call.',robotics:'The competition organizers ask whether you would mentor the junior robotics team.',standup:'A comics’ night organizer asks if you can headline next month.',pottery:'Your studio offers to display a piece with your name on the plinth.',paleontology:'The exhibit curator asks you to check the identification tags.',dueling:'The fight captain trusts you to choreograph the climactic duel.',debate:'The judges ask you to give feedback after the final round.'};story+=' '+(special[skill]||`A familiar face at the ${scene[0].toLowerCase()} asks how you learned to do that.`);fx.reputation=(fx.reputation||0)+4;}
 if(before<15&&!success&&prob(.34))story+=' An experienced hobbyist offers you a patient, useful lesson instead of laughing.';
 if(before>=65&&!success&&prob(.32)){story+=' It stings more because people expect you to be good at this. You write down what went wrong.';fx.stress=(fx.stress||0)+2;}
 const suffix=gain?` ${skillIcons[skill]||'✨'} ${skill[0].toUpperCase()+skill.slice(1)} ${before} → ${next} (+${gain}).`:` ${skillIcons[skill]||'✨'} ${skill[0].toUpperCase()+skill.slice(1)}: 100/100. You've mastered the basics; the stories keep coming.`;
 s.energy--;hobbyRecord(skill,scene[0],story,success,gain);hobbyCallback(skill,scene[0].toLowerCase(),scene[0]);s.lastActionRequested=null;outcomeModal(skillIcons[skill]||'✨',scene[0],story+suffix,fx);
}
function hobbyMenu(skill){hobbyState();const entry=hobbyById(skill);if(!entry||s.age<entry.min)return;const level=s.skills[skill]||0;const choices=entry.scenes.map(scene=>({label:scene[0],run:()=>hobbyDo(skill,scene,{difficulty:42+entry.min*.7})}));
 openModal({icon:entry.icon,title:entry.name,text:`${entry.tag} ${hobbyRank(level)} · ${level}/100. Choose what you're actually doing. Each activity uses one of this year's turns.`,choices});}
