// Music separates free setup from turns that grant skill. Writing a song creates real repertoire.
const HOBBY_SONGS=['The Moon Owes Me Five Dollars','Wednesday at the End of the World','Old Roads, New Shoes','The Last Streetlight','My Brother Stole the Chorus','Blue Hours on Maple Street','A Letter to the Ceiling','No One Told the Thunder','The Lonely Arcade','Plastic Flowers in the Rain'];
