function hobbyMusicDo(kind,style){hobbyState();const instrument=s.instrument||'guitar',w=s.hobbyWorld.music;
 if(kind==='practice'){hobbyDo('music',['Rehearse on '+instrument,
   `You finally get through a difficult passage without stopping. ${pick(['Your fingers remember the notes before you do.','The neighbor who complained last month knocks to ask what you were playing.','You record it so you can remember the feeling.'])}`,
   `You miss the same note six times in a row. On attempt seven, it starts sounding less impossible.`,
   'A street musician hears you practicing and shows you a better way to play the tricky section.'],{difficulty:26});return;}
 if(kind==='compose'){if(s.energy<1)return say('Your year is full. Write that song next time.');const name=pick(HOBBY_SONGS.concat(SONGS));const song={name,genre:style||'Folk',instrument,year:s.year,quality:hobbyRank(s.skills.music||0)};
 const scene=[`Write “${name}”`,`You finish a ${song.genre.toLowerCase()} song called “${name}.” Its bridge is your favorite thing you've written.`,`You finish “${name}.” The chorus needs work, but the strange little melody will not leave your head.`,`Your family overhears the song and starts humming the chorus at breakfast.`];
 if(s.energy<1)return say('No time left this year.');w.songs.unshift(song);w.songs=w.songs.slice(0,35);s.projects??=[];s.projects.unshift({year:s.year,age:s.age,type:'music',title:name,quality:song.quality.toLowerCase(),skill:'music',icon:'🎵',description:`${song.genre} on ${instrument}.`});hobbyDo('music',scene,{difficulty:40});return;}
 if(kind==='perform'){const title=w.songs[0]?.name||pick(SONGS);const score=s.skills.music||0;hobbyDo('music',[`Play “${title}” live`,`You play ${instrument} at the ${s.age<18?'school talent night':'community open mic'}. People sing the hook back to you.`,`Your performance gets interrupted by feedback from the speaker. You keep playing and earn a real round of applause anyway.`,`A local band asks you to audition after hearing your performance of “${title}.”`],{difficulty:64});w.gigs++;if(score>=55&&w.gigs>=2&&!w.band){w.band=pick(['The Sidewalk Astronauts','Crying at the Planetarium','Velvet Pigeons','Emergency Noodles']);addLog('🎤','You joined a band',`Your practice pays off: ${w.band} asks you to join on ${instrument}. Rehearsals are on Thursdays. Somebody always brings chips.`,'activity');save();render();}return;}
 if(kind==='band'){if(!w.band)return say('Play a few gigs and get good enough for a band first.');hobbyDo('music',[`Rehearse with ${w.band}`,`The band's new song clicks. ${w.band} books a weekend performance.`,`The drummer argues that every song needs more cowbell. The rehearsal ends early.`,`A venue owner hears one song through the open door and asks for your contact number.`],{difficulty:49});}
}
