function hobbyHeroCreate(cl){hobbyState();const names=HW_HERO_NAMES.filter(n=>n!==s.tabletopHero),name=pick(names);s.tabletopClass=cl;s.tabletopHero=name;s.tabletopCampaign??=pick(HW_CAMPAIGNS);s.hobbyWorld.party={trust:50,level:1,quests:0,fortune:0};save();openModal({icon:'🧙',title:`Meet ${name}`,text:`${name} is a level 1 ${cl} in “${s.tabletopCampaign}.” This is your character, not your actual life. Playing sessions will level them up and grow your tabletop skill.`,choices:[{label:'🎲 Play the first session',run:hobbyDnDQuest},{label:'🔁 Reroll the hero (free)',run:()=>hobbyHeroCreate(cl)},{label:'Later',run:()=>{render()}}]});}
