 const succeeded=prob(Math.min(.94,.30+before*.006+w.level*.023+bonus));const changes={tabletop:succeeded?7+r(6):3+r(4),social:succeeded?3:1,happiness:succeeded?6:-3,confidence:succeeded?4:-2};const text=succeeded?scene[1]:scene[2];s.energy--;w.quests++;w.level=1+Math.floor(w.quests/3);w.trust=lim(w.trust+(succeeded?6:-5));w.fortune+=succeeded?2:-1;
