 ...(s.tabletopClass?[{label:'📜 Your campaign record',run:()=>openModal({icon:'📜',title:'Your campaign record',text:`${s.tabletopHero}: level ${p.level}, ${p.quests} completed quests, ${p.fortune} treasure marks. ${s.tabletopCampaign}. ${s.hobbyWorld.notes.filter(x=>x.skill==='tabletop').slice(0,2).map(x=>x.result).join(' ')||'The best stories are yet to come.'}`,choices:[{label:'Back to the table',run:ll5DnD}]})}]:[])
