 const candidates=Object.entries(s.skills).filter(([id,value])=>value>=25&&(s.year-(w.last[id]??s.year))>=4&&(w.decayYears[id]??-999)!==s.year);
 if(candidates.length){const [id,value]=pick(candidates);const months=s.year-(w.last[id]??s.year),loss=Math.min(value,1+r(Math.min(4,Math.floor(months/3)+1)));s.skills[id]-=loss;w.decayYears[id]=s.year;const rust={music:'The tricky melody from your old song takes three tries to remember.',tabletop:'You find your old character sheet under a pile of mail. You no longer remember half the rules.',fencing:'Your coach gently informs you that lunging should not sound like climbing a staircase.',birdwatching:'You mix up two bird calls you once knew by heart.',archaeology:'You rediscover your old field notebook and squint at your handwriting.',pottery:'Your first bowl back at the wheel tilts dramatically to one side.',gaming:'You pick up an old game and spend the first match looking for the correct button.'};addLog('⌛',`Rusty at ${id}`,`${rust[id]||`After ${months} years away from ${id}, some of your old tricks aren't coming so easily.`} ${value} → ${s.skills[id]}.`, 'passive');}
 const practiced=Object.entries(w.last).filter(([id,y])=>y===oldYear&&(s.skills[id]||0)>=50);if(practiced.length&&prob(.26)){const [id]=pick(practiced);const awards=[`A local group asks you to demonstrate ${id} at their next meetup.`,`An old friend sends you an article about ${id} with a note: "You'd love this."`,`Your work in ${id} earns an invitation to a small community showcase.`];addLog(skillIcons[id]||'✨','Your practice gets noticed',pick(awards),'passive');statChange({confidence:3,reputation:3});}
