 const known=`<section class="card pad"><h2 class="heading">👋 People you've met</h2><p class="lead">A conversation might become a friendship. Or a grudge that survives three addresses.</p><div class="people-list">${other.map(personCard).join('')||'<p class="empty">Nobody new yet. The world is full of people.</p>'}</div></section>`;
