// CHARACTER DISPOSITIONS — small strengths and flaws that influence an entire life.
const PD=window.LITTLE_LIFE_PERSONALITY;
for(const profile of PD.profiles)if(!traits.includes(profile.id))traits.push(profile.id);
const profiles=Object.fromEntries(PD.profiles.map(p=>[p.id,p]));
const personaAxes=['warmth','nerve','discipline','curiosity','mischief'];
const personaWords={warmth:'Heart',nerve:'Nerve',discipline:'Focus',curiosity:'Wonder',mischief:'Mischief'};
const persona=person=>profiles[person?.personality]||profiles.curious;
function portraitDisposition(p){const q=persona(p);return `${q.signature[0].toUpperCase()+q.signature.slice(1)}. Their weak spot: ${q.flaw}.`;}
function personalityState(){if(!s)return null;const p=me();if(!p.personality)p.personality='curious';if(!s.persona||s.persona.owner!==p.id){const q=persona(p);s.persona={owner:p.id,axes:Object.fromEntries(personaAxes.map(k=>[k,q[k]*18])),growth:0,reflections:0,reflectionYear:-999,lastYear:-999,scenes:{},bonds:{}};}return s.persona;}
function personalityPicker(){const options=PD.choices.map(id=>{const q=profiles[id];return `<button class="personality-option ${startingPersonality===id?'selected':''}" data-personality="${esc(id)}" type="button" aria-pressed="${startingPersonality===id}"><b>${esc(id)}</b><small>${esc(q.signature)}</small></button>`}).join('');const q=profiles[startingPersonality]||profiles.curious;return `<div class="persona-pick"><label class="field-label">What are you like?</label><div class="persona-pick-grid">${options}</div><p class="persona-flaw">The catch: ${esc(q.flaw)}.</p></div>`;}
function personalitySkillBoost(skill){if(!s||!skill)return 0;const q=persona(me()),x=personalityState().axes;
 const dimension={social:'warmth',writing:'curiosity',art:'curiosity',music:'discipline',tabletop:'curiosity',gaming:'nerve',science:'curiosity',smarts:'curiosity',craft:'curiosity',coding:'discipline',grades:'discipline',sports:'nerve',confidence:'nerve',cooking:'discipline',theater:'nerve',fencing:'nerve',dueling:'nerve',robotics:'curiosity',chess:'discipline'}[skill]||'discipline';
 return Math.max(-13,Math.min(13,Math.round(((q[dimension]||0)*3+(x[dimension]||0)/15)*.65)));}
function personalitySocialModifier(p,move){const q=persona(me()),them=persona(p),x=personalityState().axes,kind=move||'talk';let amount=0;
 if(['talk','invite','gift','apologize','flirt','askout'].includes(kind))amount+=q.warmth*4+them.warmth*3;
 if(['flirt','askout','invite','standup'].includes(kind))amount+=q.nerve*4+them.nerve;
 if(['talk','apologize'].includes(kind))amount+=q.discipline*2;
 if(['insult','gossip','fight'].includes(kind))amount+=q.mischief*3-them.discipline*3;
 if(['apologize','talk'].includes(kind)&&them.id==='grudge-holder')amount-=15;
 if(kind==='gift'&&them.id==='frugal')amount-=5;
 if(kind==='invite'&&them.id==='shy')amount-=12;
 if(kind==='invite'&&them.id==='outgoing')amount+=10;
 if(kind==='talk'&&q.curiosity>0&&them.curiosity>0)amount+=9;
 return Math.max(-21,Math.min(21,Math.round(amount+(x.warmth||0)/14)));}
function personalityReaction(p,move,bond,trust){const q=persona(p),self=persona(me());const extras={
 'grudge-holder':move==='apologize'?' They say they hear you, but they are not ready to pretend it never happened.':' They bring up something you said two summers ago, accurately.',
 'prankster':` They slide a tiny plastic frog across the table. This is apparently their serious face.`,
 'shy':` They glance away before quietly admitting what they actually think.`,
 'competitive':` They ask whether this conversation counts toward the score.`,
 'nurturing':` They ask whether you have eaten anything today. You are beginning to suspect they ask everybody.`,
 'cynical':` They study you for a moment. “What’s the catch?”`,
 'optimistic':` They say tomorrow might turn out better, and seem irritatingly sincere about it.`,
 'honest':` They give you the answer without dressing it up. It is unusually refreshing.`,
 'dramatic':` They describe the moment as “the turning point of the century.”`,
 'eccentric':` They consult a tiny notebook and declare this an acceptable Tuesday.`,
 'patient':` They wait until you have completely finished speaking.`,
 'sarcastic':` “Oh, splendid,” they say, in the least splendid voice imaginable.`,
 'observant':` They mention a detail you were certain nobody noticed.`,
 'ambitious':` They check their calendar twice before replying.`,
 'loyal':` They remind you of a favor from years ago, even if you forgot it.`,
 'sneaky':` They smile as though they know one more thing than they're saying.`
 };
 const memory=p.npc?.history?.[s.playerId];
 if(memory?.encounters>=4&&memory.lastKind===move&&prob(.35))return ` ${p.name} mentions the last time you ${move==='invite'?'met up':move==='talk'?'talked':move==='gift'?'gave a gift':move==='apologize'?'tried to make things right':'did this'}. ${q.id==='grudge-holder'?'They have a disturbingly accurate memory.':q.id==='outgoing'?'They offer to make a whole afternoon of it.':'They are not quite sure whether this is becoming a tradition.'}`;
 if(['insult','gossip'].includes(move)){
  if(q.warmth>0)return ` ${p.name} looks hurt rather than angry. This was not a harmless joke.`;
  if(q.discipline>0)return ` ${p.name} writes down exactly what you said. That is not reassuring.`;
 }
 if(['talk','invite','apologize','gift','flirt','askout'].includes(move)&&self.id==='sarcastic'&&bond<0)return ` Your attempt at humor has made an already awkward moment worse.`;
 return extras[p.personality]||` ${p.name} ${q.signature}.`;
}
function personalityTuning(p,move){const q=persona(p),mine=persona(me()),compat=personalitySocialModifier(p,move);let delta=compat>10?2:compat<-10?-3:0;
 if(['insult','gossip'].includes(move)){delta+=q.warmth>0?-4:0;if(q.id==='grudge-holder')delta-=5;}
 if(move==='apologize'&&q.id==='grudge-holder')delta-=5;
 if(move==='talk'&&q.curiosity>0&&mine.curiosity>0)delta+=3;
 return {bond:delta,trust:delta*2};}
function growPersona(key,n){const x=personalityState();x.axes[key]=Math.max(-45,Math.min(45,(x.axes[key]||0)+n));x.growth++;}
function recordDisposition(effects){if(!s||!effects)return;personalityState();
 if(typeof effects.alignment==='number')growPersona('warmth',Math.max(-5,Math.min(5,Math.round(effects.alignment/3))));
 if(typeof effects.confidence==='number'&&Math.abs(effects.confidence)>=4)growPersona('nerve',Math.sign(effects.confidence));
 if(typeof effects.grades==='number'&&Math.abs(effects.grades)>=5)growPersona('discipline',Math.sign(effects.grades));
 if(typeof effects.smarts==='number'&&effects.smarts>=6)growPersona('curiosity',1);
}
function dispositionCard(){const p=me(),q=persona(p),x=personalityState(),portrait=personaAxes.map(k=>{const value=Math.max(0,Math.min(100,Math.round(50+x.axes[k])));return `<div class="persona-stat"><span>${personaWords[k]}</span><div class="persona-bar"><i style="width:${value}%"></i></div></div>`;}).join('');return `<section class="card pad persona-card"><div class="section-top"><h2 class="heading" style="margin:0">🪞 ${esc(p.name.split(' ')[0])}, the ${esc(p.personality)}</h2></div><p class="persona-voice">${esc(portraitDisposition(p))}</p><div class="persona-bars">${portrait}</div><button class="btn tiny alt" data-activity="personality" ${s.age<5||s.energy<1?'disabled':''}>📖 A day of self-discovery</button></section>`;}
function personaReflection(){
 if(s.age<5)return say('Little kids discover themselves through play.');
 if(s.energy<1)return say('You have used up your free time this year.');
 const x=personalityState();if(x.reflectionYear===s.year)return say('You already had a big moment of self-discovery this year.');
 const candidates=PD.reflections.filter(q=>s.age>=q.min&&s.age<=q.max);
 const available=candidates.filter(q=>q.id!==x.lastReflection);const scene=pick(available.length?available:candidates);
 if(!scene)return;
 const other=pick([...friends().filter(alive),...parents(me()).filter(alive),...children(me()).filter(alive)])||makeAcquaintance(true);
 const name=other.name,convert=str=>str.replaceAll('{name}',name);
 const axes=['discipline','mischief','warmth','nerve'],skills=['smarts','creativity','social','confidence'];
 openModal({icon:'🪞',title:scene.title,text:convert(scene.setup),choices:scene.choices.map(([label,good,bad],i)=>({label:convert(label),run:()=>{
  if(s.energy<1||x.reflectionYear===s.year)return;
  s.energy--;x.reflectionYear=s.year;x.lastReflection=scene.id;x.reflections++;
  const axis=axes[i],skill=skills[i],odds=Math.max(.20,Math.min(.88,.45+activityScore(skill)*.004+personalitySkillBoost(skill)*.003));
  const success=prob(odds),detail=convert(success?good:bad);
  const fx=success?[{smarts:4,reputation:3},{creativity:6,popularity:4},{social:5,happiness:5},{confidence:6,happiness:3}][i]:[{stress:3,smarts:2},{stress:4,creativity:3},{happiness:-2,social:3},{confidence:-3,stress:3}][i];
  growPersona(axis,success?5:2);consequences({...fx,alignment:i===2?5:i===1?-2:1});
  relate(other,success?(i===2?8:4):i===1?-2:2);
  addLog('🪞',scene.title,`${convert(label)} — ${detail}`,'personality');
  let evolution=null;
  if(x.reflections%4===0){const unlocked=personaAxes.slice().sort((a,b)=>x.axes[b]-x.axes[a])[0];evolution={warmth:'kind',nerve:'adventurous',discipline:'organized',curiosity:'curious',mischief:'prankster'}[unlocked];}
  save();render();
  if(evolution&&me().personality!==evolution){const change=evolution;
   openModal({icon:'🪞',title:'Something about you is changing',text:`${detail} ${name} points out that you have been acting a lot more ${change} lately.`,choices:[{label:`Maybe I'm becoming ${change}`,run:()=>{const previous=me().personality;me().personality=change;x.axes=Object.fromEntries(personaAxes.map(k=>[k,Math.max(-45,Math.min(45,Math.round((x.axes[k]+persona(me())[k]*18)/2)))]));addLog('🪞','An unexpected new side',`${me().name} used to be ${previous}. After years of decisions, a more ${change} side has come to the surface.`,'personality');save();render();}},{label:'I still feel like me',run:()=>{}}]});return;
  }
  openModal({icon:'🪞',title:success?'Well played':'Not quite the plan',text:detail,choices:[{label:'Keep going',run:()=>{}}]});
 }}))});
}

