 if(!named)return;const their=persona(named),kind=s.age<5?'baby':s.age<12?'child':s.age<18?'teen':s.age<60?'adult':'senior';
 const moment={baby:[`${named.name} tries to teach you to wave. You clap instead. They decide this is even better.`,`${named.name} builds a tower with you. You knock it down, then demand the same game five more times.`],child:[`${named.name} asks you to join a game ${here}. Your ${q.id} streak collides with their ${their.id} one over the last biscuit.`,`${named.name} brings you a puzzle. You solve it together, except for one piece stuck to their shoe.`],teen:[`${named.name} shares a secret ${here}, then asks you not to turn it into lunchroom news.`,`${named.name} invites you to a school talent show. You argue over whether the magician's rabbit is part of the band.`],adult:[`${named.name} asks your advice about changing careers. They notice your ${q.id} side before you even answer.`,`${named.name} wants to start a community garden. You spend lunch debating whether the first crop should be tomatoes or giant pumpkins.`],senior:[`${named.name} brings a crossword to the table. You disagree on the last answer for three entire cups of tea.`,`${named.name} proposes a late-night stargazing trip. The only argument is about which biscuits to bring.`]}[kind];
